const johannesburgDateKey=()=>{const parts=new Intl.DateTimeFormat("en-CA",{timeZone:"Africa/Johannesburg",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date());const part=(name:string)=>parts.find(item=>item.type===name)?.value??"0";return`${part("year")}-${part("month")}-${part("day")}`};
const johannesburgWeekKey=(instant=new Date())=>{const parts=new Intl.DateTimeFormat("en-ZA",{timeZone:"Africa/Johannesburg",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(instant);const part=(name:string)=>parts.find(item=>item.type===name)?.value??"0";const date=new Date(Date.UTC(Number(part("year")),Number(part("month"))-1,Number(part("day"))));const day=date.getUTCDay()||7;date.setUTCDate(date.getUTCDate()-day+1);return date.toISOString().slice(0,10)};
