  const move=(id:string,col:string,before?:string)=>{const item=data.tasks.find(task=>task.id===id);if(!item)return;const from=data.columns.find(column=>column.id===item.columnId)?.title;const toColumn=data.columns.find(column=>column.id===col);const to=toColumn?.title;if(!toColumn||item.columnId===col&&(!before||before===id))return;const tasks=data.tasks.filter(task=>task.id!==id);const at=before?tasks.findIndex(task=>task.id===before):-1;const now=new Date().toISOString();const wasCompleted=isCompletedColumn(data.columns.find(column=>column.id===item.columnId));const isCompleted=isCompletedColumn(toColumn);const moved:Task={...item,columnId:col,updatedAt:now,completedAt:isCompleted?(wasCompleted?item.completedAt??item.updatedAt:now):undefined};tasks.splice(at<0?tasks.length:at,0,moved);const eventId=item.columnId===col?null:uid();const events=eventId?[{id:eventId,text:"moved “"+item.title+"” from "+from+" to "+to,actor,date:now},...data.events].slice(0,100):data.events;const next={...data,tasks,events};if(eventId)queueTaskNotices(data,next,(taskId,store)=>store.events.some(event=>event.id===eventId)&&store.tasks.some(task=>task.id===taskId&&task.columnId===col&&task.updatedAt===now));setData(next)};
  const addColumn=()=>{const title=prompt("New column name");if(!title?.trim())return;setData(d=>({...d,columns:[...d.columns,{id:uid(),title:title.trim(),color:"#75a252",locked:false}]}));setToast("Column added")};
  const updateColumn=(id:string,patch:Partial<Column>)=>setData(d=>({...d,columns:d.columns.map(column=>column.id===id?{...column,...patch}:column)}));
  const deleteColumn=(column:Column)=>{if(isCompletedColumn(column)){setToast("The Completed column is reserved for task cleanup");return}if(data.columns.length<2){setToast("Keep at least one column");return}if(!confirm(`Delete “${column.title}”? Its cards will move to another column.`))return;const fallback=data.columns.find(item=>item.id!==column.id&&!isCompletedColumn(item))??data.columns.find(item=>item.id!==column.id)!;setData(d=>({...d,columns:d.columns.filter(item=>item.id!==column.id),tasks:d.tasks.map(task=>task.columnId===column.id?{...task,columnId:fallback.id,updatedAt:new Date().toISOString()}:task)}));log("deleted column “"+column.title+"”");setToast("Column deleted")};
  const moveColumn=(id:string,direction:-1|1)=>setData(d=>{const index=d.columns.findIndex(column=>column.id===id);const next=index+direction;if(index<0||next<0||next>=d.columns.length||d.columns[index].locked||d.columns[next].locked)return d;const columns=[...d.columns];[columns[index],columns[next]]=[columns[next],columns[index]];return{...d,columns}});
  const toggleColumnLock=(id:string)=>setData(d=>({...d,columns:d.columns.map(column=>column.id===id?{...column,locked:!column.locked}:column)}));
 const addAnnouncement=async(draft:AnnouncementDraft):Promise<string|null>=>{if(!draft.title.trim()||!draft.body.trim())return"Add a title and message before publishing.";if(draft.images.length&&!supabase)return"Image uploads need the Supabase database connection.";const imagePaths:string[]=[];for(const file of draft.images){if(!["image/png","image/jpeg","image/webp","image/gif"].includes(file.type)||file.size>5*1024*1024)return"Choose PNG, JPG, WEBP or GIF images smaller than 5 MB each.";const safeName=file.name.normalize("NFKD").replace(/[^a-zA-Z0-9._-]+/g,"-").slice(-80)||"announcement-image";const path=`${user.id}/${uid()}-${uid()}-${safeName}`;const {data:uploaded,error}=await supabase!.storage.from("announcement-images").upload(path,file,{cacheControl:"3600",contentType:file.type,upsert:false});if(error){if(imagePaths.length)await supabase!.storage.from("announcement-images").remove(imagePaths);return"The image could not be uploaded. Run the announcement storage setup SQL, then try again."}imagePaths.push(uploaded.path)}const announcement:Announcement={id:uid(),title:draft.title.trim(),body:draft.body.trim(),pinned:draft.pinned,category:"Team",date:new Date().toISOString(),author:actor,imagePaths};setData(d=>({...d,announcements:[announcement,...d.announcements]}));log("published announcement “"+announcement.title+"”");setAnnouncementComposer(false);setToast("Announcement published");return null};
 const deleteAnnouncement=async(announcement:Announcement)=>{if(!confirm(`Delete “${announcement.title}”?`))return;let storageFailed=false;if(supabase&&announcement.imagePaths?.length){const {error}=await supabase.storage.from("announcement-images").remove(announcement.imagePaths);storageFailed=!!error}setData(d=>({...d,announcements:d.announcements.filter(item=>item.id!==announcement.id)}));log("deleted announcement “"+announcement.title+"”");setToast(storageFailed?"Announcement deleted; an image could not be removed.":"Announcement deleted")};
 const addRoadmap=()=>{const title=prompt("Initiative name");if(!title?.trim())return;const r:Roadmap={id:uid(),title:title.trim(),category:"General",progress:0,target:"",priority:"Medium"};setData(d=>({...d,roadmaps:[r,...d.roadmaps]}));log("created roadmap “"+r.title+"”")};
 const addMilestone=()=>{const title=prompt("Milestone name");if(!title?.trim())return;const dueDate=prompt("Target date (YYYY-MM-DD, optional)")??"";const milestone:ProjectMilestone={id:uid(),title:title.trim(),description:"",dueDate:/^\d{4}-\d{2}-\d{2}$/.test(dueDate)?dueDate:"",completed:false};setData(d=>({...d,milestones:[...d.milestones,milestone]}));log("created milestone “"+milestone.title+"”")};
