function Avatar({member,small=false}:{member:Member;small?:boolean}){return <span className={"avatar "+(small?"small":"")} style={{background:member.color}} title={`${member.name}${member.handle?` · ${member.handle}`:""}`}><span>{initials(member.name)}</span>{member.avatarUrl&&<img src={member.avatarUrl} alt="" loading="lazy" referrerPolicy="no-referrer" onError={event=>{event.currentTarget.style.display="none"}}/>}</span>}
function Heading({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:React.ReactNode}){return <div className="heading"><div><small>{eyebrow}</small><h2>{title}</h2><p>{description}</p></div>{action}</div>}
