  const onWindowDragOver=(event:DragEvent)=>{if(!(event.target instanceof Node)||!board.contains(event.target))stop()};
  board.addEventListener("dragover",onDragOver);board.addEventListener("drop",stop);window.addEventListener("dragover",onWindowDragOver);window.addEventListener("dragend",stop);
