  const filteredTasks=data.tasks.filter(task=>(filter==="All priorities"||filter===task.priority)&&(assigneeFilter==="Everyone"||task.assignees.includes(assigneeFilter))&&(!query||(task.title+" "+task.description+" "+task.tags.join(" ")).toLowerCase().includes(query)));
